@spec library_spec  src=tests/specs/library_spec.lua  loc=250  sha=36fee5b  cases=16
@exercises configManager (h.cm)
@surface   cm:getAt, cm:set, cm:defaultFor
@harness   mk

# Intent
  Pin-tests for library.lua: the shared project/library tier module. The
  factory catalogue (cm:defaultFor) is a seed source, not a resolution tier --
  seedIfEmpty stocks an empty library, reloadPlan/importFactory re-import it.
  Instantiated directly over a harness cm (no in-module production caller).
  One case per verb, plus the synthetic floor's exemptions.

# Helpers
  @fn mkLib(h)  @ 10-15

# Cases
  @case 'names splits project and library, dropping the synthetic floor'  [harness]  @ 19-30
  @case 'get resolves project over library'  [harness]  @ 33-43
  @case 'localize copies a resolvable entry to project and is idempotent'  [harness]  @ 46-57
  @case 'localize skips synthetic names'  [harness]  @ 60-66
  @case 'forkToProject localizes then returns the project copy'  [harness]  @ 69-76
  @case 'publish copies the project entry to the library tier'  [harness]  @ 79-87
  @case 'publish no-ops without a project copy'  [harness]  @ 90-96
  @case 'publishOverwrites is true only for a divergent library copy'  [harness]  @ 99-116
  @case 'revert overwrites the project copy from its library source'  [harness]  @ 119-129
  @case 'revert no-ops without a library source'  [harness]  @ 132-141
  @case 'modified: false pristine, true divergent, false for a source-less entry'  [harness]  @ 144-161
  @case 'tidy drops pristine unreferenced entries, keeps inUse and divergent ones'  [harness]  @ 164-187
  @case 'delete removes from the named tier and refuses synthetic names'  [harness]  @ 190-203
  @case 'seedIfEmpty stocks an empty library from the factory catalogue, once'  [harness]  @ 206-220
  @case 'reloadPlan splits absent factory names from divergent library copies'  [harness]  @ 223-236
  @case 'importFactory copies one entry into the library, refusing synthetic'  [harness]  @ 239-248

# Uses (outbound edges)
  @use call cm:getAt  @ 50,52,55,65,75,86,95,127,139,182,198,200,202,210,212,217,244,247
  @use call cm:set  @ 53,155,174,215,228
  @use call cm:defaultFor  @ 227,244

